<?php
declare(strict_types=1);
use App\Core\Database;use App\Core\Request;use App\Services\FamilyDiscountService;use App\Services\FinancialDataService;
require dirname(__DIR__,2).'/vendor/autoload.php';
if(getenv('MIRANDA_FINANCE_TEST')!=='1'||!preg_match('/^miranda_finance_data_test_/',(string)getenv('DB_NAME'))){fwrite(STDERR,"Refusing unsafe database.\n");exit(2);} function expectDiscount(bool $v,string $m):void{if(!$v)throw new RuntimeException($m);}
$pdo=Database::connect();$x=(string)getmypid();$pdo->prepare('INSERT INTO schools(name,code,slug,email_domain,status)VALUES(?,?,?,?,"ACTIVE")')->execute(['Discount A','DA'.$x,'discount-a-'.$x,'discount-a-'.$x.'.test']);$school=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO schools(name,code,slug,email_domain,status)VALUES(?,?,?,?,"ACTIVE")')->execute(['Discount B','DB'.$x,'discount-b-'.$x,'discount-b-'.$x.'.test']);$otherSchool=(int)$pdo->lastInsertId();
$pdo->prepare('INSERT INTO academic_years(school_id,label,name,is_current)VALUES(?,?,?,1)')->execute([$school,'2026-2027','2026-2027']);$year=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO school_settings(school_id,setting_key,setting_value)VALUES(?,"active_academic_year_id",?)')->execute([$school,(string)$year]);
$pdo->prepare('INSERT INTO families(school_id,family_reference,family_name)VALUES(?,?,?)')->execute([$school,'DISC-'.$x,'Discount household']);$family=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO students(school_id,family_id,first_name,last_name,class_level,monthly_amount,status)VALUES(?,?,?,?,?,0,"REGISTERED")')->execute([$school,$family,'Discount','Child','Test']);$student=(int)$pdo->lastInsertId();
$pdo->prepare('INSERT INTO student_financial_items(school_id,student_id,academic_year_id,item_code,label,unit_amount,total_amount,discount_amount,paid_amount,status)VALUES(?,?,?,?,?,?,?,?,0,"UNPAID")')->execute([$school,$student,$year,'DISC-'.$x,'Eligible charge',100,100,0]);$item=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO student_financial_item_details(student_financial_item_id,school_id,original_amount,final_amount)VALUES(?,?,100,100)')->execute([$item,$school]);
$pdo->prepare('INSERT INTO users(school_id,first_name,last_name,email,password,role,status)VALUES(?,?,?,?,?,"admin","ACTIVE")')->execute([$school,'Discount','Tester','discount-'.$x.'@example.test','test']);$user=(int)$pdo->lastInsertId();
Request::set('auth_user',['id'=>$user,'role'=>'admin','school_id'=>$school]);$service=new FamilyDiscountService();$created=$service->create(['family_id'=>$family,'discount_type'=>'PERCENTAGE','discount_value'=>10,'reason'=>'Fixture']);expectDiscount(!isset($created['error'])&&(int)$created['impact_count']===1,'Discount creation/application failed: '.($created['error']??''));$id=(int)$created['id'];
$q=$pdo->prepare('SELECT final_amount FROM student_financial_item_details WHERE student_financial_item_id=?');$q->execute([$item]);expectDiscount((float)$q->fetchColumn()===90.0,'Discount did not set final amount');$summary=(new FinancialDataService())->getStudentFinancialSummary($school,$student);expectDiscount((float)$summary['total_due']===90.0,'Financial projection did not use discounted amount');
$again=$service->create(['family_id'=>$family,'discount_type'=>'PERCENTAGE','discount_value'=>10,'reason'=>'Duplicate']);expectDiscount(isset($again['error']),'Double discount was allowed');$changed=$service->update($id,['discount_type'=>'FIXED','discount_value'=>20,'reason'=>'Changed']);expectDiscount(!isset($changed['error']),'Discount update failed');$q->execute([$item]);expectDiscount((float)$q->fetchColumn()===80.0,'Updated discount amount incorrect');$cancel=$service->cancel($id,['reason'=>'Test']);expectDiscount(($cancel['status']??'')==='CANCELLED','Discount cancellation failed');$q->execute([$item]);expectDiscount((float)$q->fetchColumn()===100.0,'Cancellation did not restore amount');
Request::set('auth_user',['id'=>2,'role'=>'admin','school_id'=>$otherSchool]);expectDiscount($service->one($id)===false,'Cross-school discount read was allowed');echo "family discount integration: OK\n";
